WITH sod AS (
  SELECT sum(qty) AS sod_qty FROM energy_position_snapshots WHERE ts IN @day AND book = 'CRUDE' AND curve = 'BRENT'
), r AS (
  SELECT ts, sum(qty) OVER (ORDER BY ts CUMULATIVE) AS traded FROM energy_fills WHERE ts IN @day AND book = 'CRUDE' AND curve = 'BRENT'
)
SELECT r.ts, r.traded + sod.sod_qty AS crude_brent_position_bbl, 2000000.0 AS limit_bbl FROM r CROSS JOIN sod ORDER BY r.ts

